mapper.update:
UPDATE tb_node
node_id = #{nodeDto.nodeId}, node_type = #{nodeDto.nodeType}, gather_site = #{nodeDto.gatherSite}, last_updated_user =#{nodeDto.lastUpdatedUser}, site_type = #{nodeDto.siteType}, stack = #{nodeDto.stack}, site_id = #{nodeDto.siteId}, site_x = #{nodeDto.siteX}, site_y = #{nodeDto.siteY}, site_z = #{nodeDto.siteZ}, site_route = #{nodeDto.siteRoute}, last_updated_time = sysdate()
