select id,node_id from tb_node tnode,tb_material tmate


        and tnode.gather_site like  concat('%', #{monitorCondition.gatherSite},'%')


        and tmate.material_code like concat('%', #{monitorCondition.materialCode},'%')


        and tnode.node_type in

            #{nodeType}



        and tnode.site_type = #{monitorCondition.siteType}

    and tnode.status = 1 and tnode.stack_id = tmate.stack_id

order by tnode.gather_site,tnode.site_x,tnode.site_y,tnode.site_z;

SELECT tnode.id, tnode.node_id nodeId, tnode.node_type nodeType, tnode.STATUS, tnode.gather_site gatherSite, tnode.stack, tnode.site_type siteType, tnode.site_id siteId, tnode.site_x siteX, tnode.site_y siteY, tnode.site_z siteZ, tnode.site_route siteRoute, tnode.into_stack_time intoStackTime, tnode.created_time createdTime, tnode.created_user createdUser, tnode.last_updated_time lastUpdateTime, tnode.last_updated_user lastUpdateUser, tnode.stack_id stackId, tplan.stage_id maintainStageId, tstack.area_id wareAreaId FROM tb_node tnode,tb_maintran_plan tplan,tb_stack tstack
and node_id = #{nodeId} and tnode.stackId = tplan.stackId, and tstack.stackId = tplan.stackId,
and into_stack_time >= #{nodeDto.startTime}
and into_stack_time <= #{nodeDto.endTime}

select weather_name as weatherName , temp as temp, humidity as humidity , precip as precip , created_time as createdTime from tb_weather_history
and created_time >= #{monitorCondition.startTime}
and created_time <= #{monitorCondition.endTime}

